package com.fixflow.mall.api;

import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.service.OrderService;
import com.fixflow.mall.service.UserService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
@DisplayName("MallController 单元测试 - 验证 PathVariable 修复")
class MallControllerTest {

    @Mock
    private UserService userService;

    @Mock
    private OrderService orderService;

    @InjectMocks
    private MallController mallController;

    private MallOrder testOrder;

    @BeforeEach
    void setUp() {
        testOrder = new MallOrder();
        testOrder.setId(123L);
        testOrder.setUserId(1L);
    }

    @Test
    @DisplayName("正向测试: 修复后 getOrder 方法能根据 orderId 正确返回订单")
    void getOrder_ValidOrderId_ReturnsOrder() {
        // Arrange
        Long orderId = 123L;
        when(orderService.findOrder(orderId)).thenReturn(testOrder);

        // Act
        MallOrder result = mallController.getOrder(orderId);

        // Assert
        assertNotNull(result);
        assertEquals(orderId, result.getId());
        verify(orderService, times(1)).findOrder(orderId);
    }

    @Test
    @DisplayName("边界测试: 原来导致异常的路径变量 'id' 与 'orderId' 不匹配问题已修复")
    void getOrder_PathVariableMismatchFixed_NoExceptionThrown() {
        // Arrange
        Long orderId = 456L;
        MallOrder expectedOrder = new MallOrder();
        expectedOrder.setId(orderId);
        when(orderService.findOrder(orderId)).thenReturn(expectedOrder);

        // Act & Assert - 修复前这里会抛出 MissingPathVariableException
        assertDoesNotThrow(() -> {
            MallOrder result = mallController.getOrder(orderId);
            assertNotNull(result);
            assertEquals(orderId, result.getId());
        });
    }

    @Test
    @DisplayName("边界测试: 当订单不存在时返回 null")
    void getOrder_OrderNotFound_ReturnsNull() {
        // Arrange
        Long nonExistentOrderId = 999L;
        when(orderService.findOrder(nonExistentOrderId)).thenReturn(null);

        // Act
        MallOrder result = mallController.getOrder(nonExistentOrderId);

        // Assert
        assertNull(result);
        verify(orderService, times(1)).findOrder(nonExistentOrderId);
    }

    @Test
    @DisplayName("正向测试: nickname 方法能正确返回用户昵称")
    void nickname_ValidUserId_ReturnsNickname() {
        // Arrange
        Long userId = 1L;
        String expectedNickname = "TestUser";
        when(userService.getNickname(userId)).thenReturn(expectedNickname);

        // Act
        String result = mallController.nickname(userId);

        // Assert
        assertEquals(expectedNickname, result);
        verify(userService, times(1)).getNickname(userId);
    }

    @Test
    @DisplayName("正向测试: createOrder 方法能正确创建订单")
    void createOrder_ValidRequest_ReturnsCreatedOrder() {
        // Arrange
        CreateOrderRequest request = new CreateOrderRequest();
        MallOrder createdOrder = new MallOrder();
        createdOrder.setId(100L);
        when(orderService.createOrder(request)).thenReturn(createdOrder);

        // Act
        MallOrder result = mallController.createOrder(request);

        // Assert
        assertNotNull(result);
        assertEquals(100L, result.getId());
        verify(orderService, times(1)).createOrder(request);
    }

    @Test
    @DisplayName("正向测试: firstItem 方法能正确返回订单的第一个商品 ID")
    void firstItem_ValidOrderId_ReturnsFirstItemId() {
        // Arrange
        Long orderId = 123L;
        Long expectedFirstItemId = 1001L;
        when(orderService.firstItemId(orderId)).thenReturn(expectedFirstItemId);

        // Act
        Long result = mallController.firstItem(orderId);

        // Assert
        assertEquals(expectedFirstItemId, result);
        verify(orderService, times(1)).firstItemId(orderId);
    }
}
